<!-- This file is generated by AI. -->
<!--
  参考音频裁剪对话框。

  音频**过长**时弹出: 展示波形, 自动放置建议的裁剪区间, 允许拖拽调整与试听, 实际裁剪由后端执行
  (后端同时负责 3~10 秒约束的最终校验)。音频**过短**时不弹此对话框, 由后端静默补尾 ——
  本组件在那种情况下只做提示。

  调用方契约: 区间由 `AddReferenceDialog` 通过 `suggestedStart` / `suggestedEnd` 传入,
  参考文本与语言是**受控**的 (父组件持有), 确认时只把区间交回去。

  ⚠️ 试听复用 `lib/audio.ts` 的全局单例, 不自己 `new Audio` —— 否则这里响的同时别处也在响。

  ⚠️ 不带 `<style>` 块 —— 类名来自全局 `styles.css`。
-->
<script lang="ts">
  import { onDestroy, untrack } from 'svelte';

  import { voiceReadAudio, voiceWaveform, type Waveform } from '../commands/voice';
  import { playAudioRange, playingKey, stopAudio, subscribeAudio } from '../lib/audio';
  import { LANGUAGE_LABELS, MAX_REF_SECONDS, MIN_REF_SECONDS } from '../voice/types';
  import AppDialog from './AppDialog.svelte';
  import Button from './Button.svelte';
  import Select from './Select.svelte';

  let {
    /** 源音频路径 */
    path,
    /** 自动建议区间的起点 (秒) */
    suggestedStart,
    /** 自动建议区间的终点 (秒); `suggestedEnd < 0` 表示无需裁剪 */
    suggestedEnd,
    text,
    language,
    /** 是否要求参考文本非空后才可以确认 */
    requireText = false,
    busy,
    error,
    onTextChange,
    onLanguageChange,
    onCancel,
    onConfirm,
  }: {
    path: string;
    suggestedStart: number;
    suggestedEnd: number;
    text: string;
    language: string;
    requireText?: boolean;
    busy: boolean;
    error: string | null;
    onTextChange: (text: string) => void;
    onLanguageChange: (language: string) => void;
    onCancel: () => void;
    onConfirm: (start: number, end: number) => void;
  } = $props();

  const HEIGHT = 96;
  const HANDLE_HIT = 8;
  /** 本对话框预览用的音源标识 (全局单例按它判断"响的是不是我") */
  const PREVIEW_KEY = 'trim-preview';

  const needsTrim = $derived(suggestedEnd >= 0);

  let waveform = $state<Waveform | null>(null);
  /** 区间初值: 无需裁剪时终点等波形到位后再补 (初始 0) */
  let start = $state(untrack(() => suggestedStart));
  let end = $state(untrack(() => (suggestedEnd >= 0 ? suggestedEnd : 0)));
  let playing = $state(false);
  let canvas: HTMLCanvasElement | undefined = $state();
  /** 正在拖的是哪一端 */
  let dragging = $state<'start' | 'end' | null>(null);

  let cancelPreview: (() => void) | null = null;
  const unsubscribe = subscribeAudio((key) => (playing = key === PREVIEW_KEY));

  onDestroy(() => {
    unsubscribe();
    cancelPreview?.();
    // 离开对话框就停掉预览: 否则关掉之后声音还在响, 而且找不到是谁在响
    if (playing) stopAudio();
  });

  $effect(() => {
    const target = path;
    let disposed = false;
    void (async () => {
      try {
        const data = await voiceWaveform(target);
        if (disposed) return;
        waveform = data;
        if (!needsTrim) end = data.duration;
      } catch {
        // 波形不可用时仍允许确认 (后端会重新探测)
      }
    })();
    return () => {
      disposed = true;
      // 用 `playingKey()` 而不是读 `playing`: 读响应式状态会让这个 effect 在每次播放状态
      // 变化时重跑, 也就是**每点一次试听都重新拉一遍波形**。
      if (playingKey() === PREVIEW_KEY) stopAudio();
    };
  });

  const duration = $derived(waveform?.duration ?? Math.max(end, suggestedStart, 1));
  const shownStart = $derived(needsTrim ? start : 0);
  const shownEnd = $derived(needsTrim ? end : duration);
  const selected = $derived(Math.max(0, shownEnd - shownStart));
  const columns = $derived(waveform?.columns ?? 0);

  $effect(() => {
    const element = canvas;
    const data = waveform;
    const from = shownStart;
    const to = shownEnd;
    const total = duration;
    const cols = columns;
    if (!element) return;
    const context = element.getContext('2d');
    if (!context) return;

    const width = element.clientWidth || 640;
    const dpr = window.devicePixelRatio || 1;
    element.width = width * dpr;
    element.height = HEIGHT * dpr;
    context.setTransform(dpr, 0, 0, dpr, 0, 0);
    context.clearRect(0, 0, width, HEIGHT);

    // 选区底色
    if (needsTrim) {
      const left = (from / total) * width;
      const right = (to / total) * width;
      context.fillStyle = 'rgba(80, 160, 255, 0.14)';
      context.fillRect(left, 0, right - left, HEIGHT);
    }

    if (data && cols > 0) {
      const middle = HEIGHT / 2;
      context.strokeStyle = 'rgba(128, 128, 128, 0.85)';
      context.beginPath();
      for (let column = 0; column < cols; column++) {
        const x = (column / cols) * width;
        const min = data.mins[column] ?? 0;
        const max = data.maxs[column] ?? 0;
        context.moveTo(x, middle - max * (HEIGHT / 2 - 2));
        context.lineTo(x, middle - min * (HEIGHT / 2 - 2));
      }
      context.stroke();
    }

    // 裁剪手柄
    if (needsTrim) {
      context.fillStyle = 'rgba(0, 120, 212, 0.9)';
      for (const position of [from, to]) {
        const x = (position / total) * width;
        context.fillRect(x - 1, 0, 2, HEIGHT);
      }
    }
  });

  function positionFromEvent(event: PointerEvent): number {
    const element = canvas;
    if (!element) return 0;
    const rect = element.getBoundingClientRect();
    const ratio = (event.clientX - rect.left) / Math.max(1, rect.width);
    return Math.min(duration, Math.max(0, ratio * duration));
  }

  function applyDrag(position: number): void {
    if (dragging === 'start') start = Math.min(position, end - 0.1);
    else if (dragging === 'end') end = Math.max(position, start + 0.1);
  }

  function onPointerDown(event: PointerEvent): void {
    const element = canvas;
    if (!needsTrim || !element) return;
    const rect = element.getBoundingClientRect();
    const position = positionFromEvent(event);
    const startX = (start / duration) * rect.width;
    const endX = (end / duration) * rect.width;
    const localX = event.clientX - rect.left;
    // 命中判定: 先看离哪一端更近, 都不在命中范围内才按"点在手柄左边还是右边"
    dragging =
      Math.abs(localX - startX) <= HANDLE_HIT && Math.abs(localX - startX) <= Math.abs(localX - endX)
        ? 'start'
        : Math.abs(localX - endX) <= HANDLE_HIT
          ? 'end'
          : localX < startX
            ? 'start'
            : 'end';
    applyDrag(position);
    element.setPointerCapture(event.pointerId);
  }

  function onPointerMove(event: PointerEvent): void {
    if (!dragging) return;
    applyDrag(positionFromEvent(event));
  }

  function onPointerUp(event: PointerEvent): void {
    dragging = null;
    canvas?.releasePointerCapture(event.pointerId);
  }

  async function togglePlay(): Promise<void> {
    cancelPreview?.();
    cancelPreview = null;
    if (playing) {
      stopAudio();
      return;
    }
    try {
      const dataUrl = await voiceReadAudio(path);
      cancelPreview = playAudioRange(dataUrl, PREVIEW_KEY, shownStart, shownEnd);
    } catch {
      playing = false;
    }
  }

  const overLimit = $derived(selected > MAX_REF_SECONDS + 1e-3);
  const tooShort = $derived(selected < MIN_REF_SECONDS);
  const canConfirm = $derived(!busy && !overLimit && (!requireText || text.trim().length > 0));

  const durationLabel = $derived(
    !needsTrim
      ? `当前 ${duration.toFixed(2)}s，不足 ${MIN_REF_SECONDS}s 的部分会在尾部补静音`
      : `当前 ${selected.toFixed(2)}s（上限 ${MAX_REF_SECONDS}s）${tooShort ? '，不足部分会在尾部补静音' : ''}`
  );
</script>

<AppDialog title={needsTrim ? '裁剪参考音频' : '添加参考音频'} size="large" height={560} onClose={onCancel}>
  <p class="voice-dialog-hint">
    GPT-SoVITS 要求参考音频时长在 {MIN_REF_SECONDS}~{MAX_REF_SECONDS} 秒之间。
    {needsTrim ? '已按静音边界自动放置裁剪区间，可拖拽两端微调。' : '该音频较短，会在尾部补静音。'}
  </p>

  <div class="trim-waveform">
    <canvas
      bind:this={canvas}
      style="height:{HEIGHT}px"
      onpointerdown={onPointerDown}
      onpointermove={onPointerMove}
      onpointerup={onPointerUp}
      onpointercancel={onPointerUp}
    ></canvas>
  </div>

  <div class="trim-toolbar">
    <span class="trim-readout">{durationLabel}</span>
    {#if needsTrim}
      <span class="trim-range">{shownStart.toFixed(2)}s → {shownEnd.toFixed(2)}s</span>
    {/if}
  </div>

  <div class="voice-row">
    <label class="voice-field">
      <span class="voice-label">语言</span>
      <Select
        value={language}
        title="参考文本使用的语言"
        options={Object.entries(LANGUAGE_LABELS).map(([value, label]) => ({ value, label }))}
        onchange={onLanguageChange}
      />
    </label>
  </div>

  <label class="voice-field">
    <span class="voice-label">
      参考文本
      <span class="voice-required">*</span>
      <span class="voice-label-note">必须与音频逐字一致</span>
    </span>
    <input
      class="ui-input"
      value={text}
      placeholder="例如：我有什么不对劲的地方吗？"
      oninput={(event) => onTextChange(event.currentTarget.value)}
    />
  </label>

  {#if error}
    <p class="voice-error">{error}</p>
  {/if}
  {#if overLimit}
    <p class="voice-error">裁剪区间超过 {MAX_REF_SECONDS}s 上限</p>
  {/if}

  {#snippet footerLeading()}
    <Button icon={playing ? 'Stop' : 'Play'} onclick={() => void togglePlay()}>
      {playing ? '停止' : '试听'}
    </Button>
  {/snippet}

  {#snippet footer()}
    <Button disabled={busy} onclick={onCancel}>取消</Button>
    <Button
      appearance="primary"
      disabled={!canConfirm}
      onclick={() => onConfirm(shownStart, needsTrim ? shownEnd : -1)}
    >
      {busy ? '处理中…' : '确认'}
    </Button>
  {/snippet}
</AppDialog>
